from pathlib import Path

def test_docs_contract():
    text='\n'.join(Path(p).read_text(encoding='utf-8') for p in ['docs/atlas_scale_master_roadmap.md','docs/atlas_development_handoff.md','docs/atlas_unified_autopilot_checkpoint.md','docs/atlas_autopilot_current_status.md','docs/atlas_autopilot_scale_master_plan.md','docs/atlas_thinui_readiness.md','docs/atlas_autonomous_execution_readiness_policy.md','docs/atlas_self_development_rules.md'])
    for s in ['PR-ATLAS-SCALE-91','PR-ATLAS-SCALE-92: Readiness gate rollup / Level-0 completion checkpoint','PR-ATLAS-SCALE-93: Level-1 guarded execution design checkpoint','PR-ATLAS-SCALE-90B','metadata-only self-improvement gate','metadata-only self-improvement gate','self-improvement gate does not generate patches','self-improvement gate does not apply patches','self-improvement gate does not run safe_apply','self-improvement gate does not run tests or verification','self-improvement gate does not run git commands','autonomous self-improvement remains disabled','automatic self-modification remains disabled','strict-gate by default','self_improvement_gate_ready does not authorize automatic execution','self_improvement_gate_ready does not authorize patch apply','self_improvement_gate_ready does not authorize git operations','requested_operation must be none for remote git readiness','invalid or unreadable reference manifests block remote git readiness','Level 0 manual-only','single existing manual action only','out-of-order architecture checkpoint','fully autonomous code agent']:
        assert s.lower() in text.lower()
